                'نافذة الرصد في الاستهلال قصيرة، وقد يغيّر فرق دقائق في التوقيت نتيجة الرصد. ولذلك فإن الإلمام بأنظمة الزمن وبالتعريف الدقيق لـ«الغروب» ضروري للراصد.',
