                'يُعلَن زمن الاقتران وكثير من الأحداث الفلكية في التقاويم والبرامج عادةً بـ«التوقيت العالمي» (UTC). ويُحصل على التوقيت المحلي بإضافة فرق المنطقة الزمنية (والتوقيت الصيفي حيث يُطبَّق) إلى التوقيت العالمي. فمثلاً اقتران في الساعة ١٤:٣٠ بالتوقيت العالمي يقع في الساعة ١٨:٠٠ بالتوقيت المحلي في منطقة فرقها عن التوقيت العالمي ٣ ساعات و٣٠ دقيقة. وقد تتغير قواعد المناطق الزمنية والتوقيت الصيفي؛ ولذلك يجب أن تنسجم إعدادات الوقت في الجهاز والتطبيق مع المنطقة الزمنية لموقع الرصد.',
                'تعريف غروب الشمس',
                'لحظة غروب الشمس هي اللحظة التي تختفي فيها الحافة العليا لقرص الشمس عند الأفق في نظر الراصد. ويتضمن هذا التعريف عاملين: نصف القطر الظاهري للشمس (نحو ١٦ دقيقة قوسية) والانكسار الجوي القياسي عند الأفق (نحو ٣٤ دقيقة قوسية). ومجموعهما نحو ٥٠ دقيقة قوسية (نحو ٠٫٨٣°)؛ أي إن مركز قرص الشمس لحظة الغروب يقع هندسياً نحو ٠٫٨٣° تحت الأفق الرياضي. ويُحسب طلوع القمر وغروبه كذلك بالاستناد إلى الحافة العليا للقرص، مع مراعاة الانكسار الجوي واختلاف منظر القمر.',
                'أثر ارتفاع موقع الرصد',
                'كلما علا موقع الرصد بدا الأفق أبعد وأخفض. وهذا «انخفاض الأفق» (Dip) يساوي تقريباً $1.76\\\\sqrt{h}$ دقيقة قوسية، حيث $h$ ارتفاع عين الراصد فوق سطح البحر بالأمتار. فمثلاً عند ارتفاع ١٠٠ م يبلغ الانخفاض نحو ١٧٫٦ دقيقة قوسية. ونتيجة لذلك تغرب الشمس والقمر متأخرين قليلاً في الموقع المرتفع (في العروض المتوسطة عادةً نحو دقيقة إلى دقيقتين لارتفاع عدة عشرات إلى مئة متر). والأوقات التي تحسبها البرامج عادةً للأفق الرياضي والارتفاع الأساسي ولا تراعي تماماً أثر ارتفاع الموقع أو العوائق المحلية.',
                'الأفق المرئي والعوائق',
                'إذا كان في الأفق الغربي جبل أو بناء فإن الشمس والقمر يختفيان عن النظر قبل الوقت المحسوب للأفق الرياضي. وعند التخطيط للرصد ينبغي اتخاذ الوقت الفعلي لاختفاء القمر خلف العائق (لا وقت الغروب الرياضي) أساساً (الدرس ٦.١).',
