                'يبدأ الشهر القمري فلكياً عند «الاقتران» (Conjunction). والاقتران هو اللحظة التي يتساوى فيها الطول الكسوفي (طول دائرة البروج) للقمر والشمس؛ أي إن القمر، في حركته المدارية، يتجاوز الشمس. ويُحسب «عمر الهلال» (الدرس ٣.١) من هذه اللحظة. ويُستخدم في الحسابات الفلكية تعريفان للاقتران، والفرق بينهما مهم في الاستهلال.',
