                '١. المدار الإهليلجي وتغير سرعة القمر: مدار القمر إهليلجي، وسرعته الزاوية في الحضيض (أقرب نقطة إلى الأرض) أكبر منها في الأوج (أبعد نقطة). فقد يكون لهلال عمره ١٦ ساعة في الحضيض، بسبب سرعته المدارية الأكبر، استطالة أكبر عن الشمس فيكون أسهل رؤية من هلال عمره ٢٢ ساعة في الأوج.',
