              title: 'زاوية الطور والسطوع النسبي للسماء',
              body: [
                'لا تتوقف رؤية جرم خافت على ضوئه هو فحسب؛ فضوء الخلفية لا يقل أهمية. ويصف معاملا «زاوية الطور» و«السطوع النسبي للسماء» هذا التفاعل الضوئي بين القمر وخلفيته.',
                '١. زاوية الطور (Phase Angle)',
                'الفرق بين زاوية الطور والاستطالة هو في موضع تكوّن الزاوية:',
                'الاستطالة: الزاوية المتكوّنة عند عين الراصد (على الأرض) بين الشمس والقمر.',
                'زاوية الطور: الزاوية المتكوّنة عند مركز القمر بين اتجاه الأرض واتجاه الشمس.',
                'وتُستخرج نسبة الإضاءة من زاوية الطور:',
                '$Illumination \\\\approx \\\\frac{1 + \\\\cos(Phase Angle)}{2}$',
                'عند البدر تقترب زاوية الطور من ٠°، وعند المحاق تقترب من $180^\\\\circ$. فمثلاً تعني زاوية طور $162.48^\\\\circ$ أن الشمس تكاد تكون خلف القمر وأن ضوءها يسقط على حافة القمر بزاوية مائلة جداً؛ وتبلغ نسبة الإضاءة في هذه الحالة نحو ٢٫٣٪.',
                '٢. السطوع النسبي للسماء (Relative Sky Brightness)',
                'رؤية الهلال مسألة تباين: فحتى الهلال الساطع لا يُرى على خلفية شديدة السطوع. وبعد غروب الشمس تظلم السماء تدريجياً عبر الشفق المدني (ارتفاع الشمس حتى −٦°)، فالشفق البحري (−٦° إلى −١٢°)، فالشفق الفلكي (−١٢° إلى −١٨°). ويتوقف سطوع خلفية السماء عند الأفق الغربي أساساً على الارتفاع السالب للشمس. فمثلاً قد يكون ارتفاع الشمس $-4.893^\\\\circ$.',
                'حدود النموذج: سطوع السماء في التطبيق تقريب نوعي قائم على ارتفاع الشمس وليس نموذجاً ضوئياً قياسياً دقيقاً. ويتطلب النمذجة الدقيقة معرفة مقدار الجسيمات العالقة (الهباء الجوي) والرطوبة والغبار في اللحظة نفسها. ومع ذلك فإن هذا التقريب (مثلاً ٤٠٪) يدل على أن السماء ما زالت مضيئة نسبياً، وعلى أن من الواجب، إذا كان سمك الهلال صغيراً، انتظار ازدياد إظلام السماء.',
              ],
