                '٢. معيار إلياس (Ilyas)',
                'تبنّى محمد إلياس، الباحث الماليزي، في الثمانينيات والتسعينيات نهجاً جغرافياً لمسألة رؤية الهلال، وطرح مفهوم «خط التاريخ القمري» (Lunar Date Line). ويبيّن هذا النهج أن إمكان رؤية الهلال يتغير بالانتقال من شرق الأرض إلى غربها بسبب الزيادة التدريجية في عمر الهلال. ويقوم معيار إلياس (١٩٨٨) على معاملات هندسية لموضعي القمر والشمس، ويُستخدم في رسم خطوط الرؤية العالمية.',
                '٣. معيار ماببيمس (MABIMS)',
                'معيار ماببيمس هو في الأساس معيار تقويمي اتفقت عليه الدول الأعضاء (بروناي وإندونيسيا وماليزيا وسنغافورة) وله طابع تنفيذي وقانوني. ويشترط إصداره الجديد (المعروف بـ«نيو-ماببيمس») ارتفاعاً لا يقل عن ٣° واستطالة لا تقل عن ٦٫٤° للقمر عند غروب الشمس. وهذا المعيار مفيد للمستخدمين الراغبين في معرفة اتفاق الهلال مع المعايير التقويمية لهذه الدول.',
                '٤. معيار سرودي (Soroudi Criterion)',
                'سمّى الدكتور محمد مهدي سرودي معياره باسم جده المرحوم الحاج علي أصغر سرودي، وهو يصنّف إمكان رؤية الهلال في طبقتين:',
                'الطبقة الأولى («الرتبة الأساس»): هي الرتبة التي تعطيها صيغة يالوب (١٩٩٧)، لأن هذه الصيغة معايَرة على ٢٩٥ رصداً حقيقياً.',
                'الطبقة الثانية («سقف الإجماع»): تخفض الرتبة الأساس فقط إذا لم تؤيدها معايير مستقلة أخرى. فإذا أعطى معيارا SAAO (كالدويل ولاني، ٢٠٠١) وإلياس (١٩٨٨) كلاهما الرتبة F أصبح السقف النهائي C؛ وإذا أعطى أحدهما فقط F أصبح السقف B؛ وإلا بقيت الرتبة الأساس دون تغيير. ويُعرض معيار عودة في التقرير، لكنه لما كانت معاملاته قريبة عملياً من يالوب ولا يُعدّ شاهداً مستقلاً (الدرس ٤.٣)، فلا دور له في حساب السقف.',
