                'ووفق صاحب المعيار فإنه «إجماع متعدد الهندسات»، ويُصرَّح بحدوده صراحة: فهو ليس نموذجاً فيزيائياً كاملاً لضوء الشفق وتباين العين، ولا نموذجاً إحصائياً مطابَقاً على بيانات رصد جديدة. إنه يوازن فحسب بين ثلاث صيغ هندسية قائمة (يالوب وSAAO وإلياس) بقاعدة شفافة ودون معامل جديد.',
