                '$$W = SD \\\\times (1 - \\\\cos ARCL)$$',
                'الخطوة ٢: حساب q وV',
                '$$q = \\\\frac{ARCV - (11.8371 - 6.3226W + 0.7319W^2 - 0.1018W^3)}{10}$$',
                '$$V = ARCV - (7.1651 - 6.3226W + 0.7319W^2 - 0.1018W^3)$$',
                'المثال الأول',
                'المدخلات: $SD = 15.5\'$ و$ARCL = 12^\\\\circ$ و$ARCV = 9.5^\\\\circ$ (عند الزمن الأمثل للرؤية).',
                '١. السُّمك: $\\\\cos 12^\\\\circ \\\\approx 0.97815$، فيكون $W = 15.5 \\\\times 0.02185 \\\\approx 0.339\'$.',
                '٢. متعددة حدود يالوب: $11.8371 - 6.3226(0.339) + 0.7319(0.1149) - 0.1018(0.03896) \\\\approx 9.776$.',
                '٣. $q = (9.5 - 9.776)/10 \\\\approx -0.028$ ← الرتبة C في يالوب (قد تلزم أداة بصرية للعثور على الهلال).',
                '٤. $V = 9.5 - (9.776 - 4.672) \\\\approx 4.40$ ← الرتبة B في عودة (رؤية بالأداة البصرية، وقد تكون بالعين المجردة).',
