                'تعتمد العصيّات على صباغ يُسمّى «رودوبسين» (الأرجوان البصري). فالضوء الساطع يفكّك الرودوبسين (التبييض)، وفي الظلام يبدأ تجديده. ويستغرق التجديد الكامل زمناً: فبلوغ الحساسية القصوى يحتاج نحو ٢٠ إلى ٣٠ دقيقة أو أكثر. وتؤدي نظرة وجيزة إلى ضوء أبيض ساطع (مصابيح سيارة أو فلاش أو شاشة هاتف مضيئة) إلى إتلاف جزء كبير من هذا التكيّف ويجب بدء التجديد من جديد.',
                'اعتبار خاص في الاستهلال',
                'يُجرى رصد هلال المساء في الشفق والسماء تظلم. وفي هذه الفترة لا تبلغ العين التكيّف الكامل، لكن أيّ درجة من التكيّف تحققت تؤثر في القدرة على كشف هلال خافت منخفض التباين. ولذلك ينبغي تجنب التعرض للإضاءة الاصطناعية الساطعة في دقائق الرصد.',
                'السلوك الموصى به: الضوء الأحمر',
                'حساسية الرودوبسين للضوء الأحمر طويل الموجة ضعيفة جداً، والضوء الأحمر منخفض الشدة يسبب تبييضاً قليلاً. ولذلك يُنصح في موقع الرصد باستخدام مصباح يدوي خافت ذي مرشح أحمر لقراءة الخرائط وضبط الأدوات واستخدام الهاتف المحمول. وهذا يحفظ التكيّف مع الظلام أفضل من الضوء الأبيض، لكنه لا يضمنه ضماناً كاملاً؛ ولذلك يجب إبقاء شدة الضوء في حدها الأدنى.',
