                'المناظير اليدوية (مثل $7\\\\times50$ أو $10\\\\times50$) خفيفة ويمكن استخدامها باليد، لكن قدرتها على الأهلّة الرفيعة جداً أضعف. أما مناظير الاستهلال الكبيرة (مثل $20\\\\times80$ أو $25\\\\times100$) فتجمع ضوءاً أكثر وتناسب الأهلّة الحرجة أكثر، لكن يجب تثبيتها على حامل ثلاثي القوائم؛ فارتعاش اليد يشوّش خيال الهلال الرفيع.',
                'الحدقة الخارجة (Exit Pupil)',
