                'التلسكوبات الكاسرة (Refractors): تعمل بالعدسات، ولأنها بلا مرآة ثانوية ولا عائق في مسار الضوء فهي عادةً أفضل تبايناً. والكاسرات اللاكروماتية (Apo) ذات الفتحة نحو ٨٠ إلى ١٢٠ ملم مناسبة جداً للاستهلال.',
