                'السيناريو الأول (أفق ٠°): الراصد في سهل مفتوح أو على ساحل. تغرب الشمس ويبقى الهلال فوق الأفق مدة (نحو ٢٠ دقيقة) قبل بلوغه، وتظلم السماء خلالها.',
