                'الطريقة: في النهار (مثلاً قبل الغروب بساعة) وجّه الأداة البصرية إلى هدف أرضي بعيد، على بعد ٢ إلى ٣ كيلومترات على الأقل (كقمة جبل أو برج اتصالات أو مبنى بعيد)، واضبط الخيال لأقصى وضوح. وبذلك تكون الأداة مضبوطة على «اللانهاية». ثم ثبّت المُبَؤِّر ببرغي القفل (أو بشريط لاصق) حتى لا يتغير أثناء الحمل في الظلام. تنبيه: يجب ألا تُوجَّه الأداة في هذه المرحلة نحو الشمس أو قربها.',
