                'الميزة العلمية للرصد نهاراً',
                'في النهار قد يكون القمر على ارتفاع أكبر فوق الأفق. وفي الارتفاعات الأعلى تكون الكتلة الهوائية أصغر (الدرس ٣.١٢)، ويقل أثر غبار الأفق ورطوبته وانقلاب الحرارة والعوائق الأرضية. ومع أن سماء النهار شديدة الإضاءة فإن زيادة شفافية الغلاف الجوي في الارتفاعات الأعلى قد تزيد إمكان رؤية الأهلّة شديدة الحرج. غير أن السماء قرب الشمس شديدة السطوع ويقل تباين الهلال كثيراً؛ ولذلك تُطبَّق هذه الطريقة مع كاميرا حساسة ومرشحات (الدرسان ٥.٦ و٨.١) أكثر من الرصد البصري.',
