                ' السيد كاظم الحائري: «لا يبعد كفاية إمكانية الرؤية بالعين المسلّحة» (الفتاوى الواضحة، ص ٧١٠)؛ ويُشترط على الأقل إمكان رؤية الهلال ولو بالعين المسلّحة مع صرف النظر عن مانع كالغيم (الفتاوى المنتخبة، ص ١٩٥، م ١).',
                'رأي  بهجت ',
                'تتباين التقارير في رأي  بهجت . فقد تلقّى جامع المصدر في أواخر شتاء ١٣٩٧ هـ.ش (٢٠١٩م) جواباً من مكتبه في قم بأنه لم يكن يقول بكفاية الرؤية بالعين المسلّحة، بل يرى جواز استخدام الأداة لمعرفة موضع الهلال، ثم يشترط رؤيته بالعين العادية بعد ذلك. وفي ربيع ١٤٠١ هـ.ش (٢٠٢٢م) نُشرت في موقع مركز تنظيم ونشر آثاره مادة تتناول كفاية الرؤية بالعين المسلّحة عنده، وعند السؤال مجدداً من المكتب في أواخر شتاء ١٤٠١ هـ.ش (٢٠٢٣م) أُجيب بأنه كان يقول بكفاية الرؤية بالعين المسلّحة بشرط حصول الاطمئنان من قول من رأوه بها.',
