                'إضافة إلى مسألة «العين المسلّحة أو غير المسلّحة»، ثمة نقاط تكميلية في الفتاوى لها أهمية عملية للراصد.',
                '١. التفريق بين «تحديد موضع الهلال» و«رؤية الهلال»',
