              num: '11.1',
              title: 'بنية تقرير الرصد القياسي الموثَّق',
              body: [
                'باختيار خيار «تسجيل تقرير» في قسم الاستهلال يظهر نموذج صُمّم وفق الأنماط الشائعة لكتابة تقارير رصد الأهلّة. وإتمام الحقول بدقة يصنع الفرق بين ادعاء بسيط وبيانات علمية قابلة للتقييم.',
                '١. الهوية وموقع الرصد',
                'تسجيل الاسم واللقب إلزامي، وتسجيل البريد الإلكتروني اختياري. ويسأل التطبيق هل موقع الرصد هو المدينة المختارة في الإعدادات. والدقة المكانية ضرورية للتحقق من صحة الحسابات الهندسية.',
                'زمن الرصد: التاريخ (مع إمكان اختيار التقويم الشمسي الهجري أو الميلادي) والساعة والدقيقة بدقة. ولا يُقبل تاريخ الرصد إلا ضمن الفترة المنطقية «من لحظة الاقتران إلى ٦٠ ساعة بعدها» منعاً لإدخال بيانات غير ذات صلة.',
                'نتيجة الرصد: أربعة خيارات: «رأيته بالعين العادية» و«رأيته بالأداة فقط» و«لم أره» و«لم يُجرَ الرصد» (بسبب عوائق قاهرة كالعاصفة). والاختيار الدقيق بينها مهم لتمييز نوع الرؤية فلكياً وفقهياً (الدرسان ٩.٢ و٩.٣).',
                'الأدوات والظروف الجوية: إذا استُخدمت أداة تُحدَّد نوعها (تلسكوب أو منظار ثنائي أو كاميرا أو مستشعر CCD وغيرها). ثم تُسجَّل حالة الطقس (صافٍ أو غائم جزئياً أو غائم أو غبار أو ضباب) وجودة شفافية الأفق (من ممتازة إلى ضعيفة) ونسبة الغطاء السحابي بمنزلق. والظروف الجوية من العوامل المهمة في تقييم أي تقرير (الدرسان ٦.٢ و٦.٤).',
                '٢. إرفاق الوثائق والتأكيد النهائي',
                'في نهاية النموذج أقسام تكميلية: نص التقرير (مربع اختياري لشرح الطرائق المستخدمة، مثل «استُخدم كوكب الزهرة دليلاً»)، ورفع صورة (التقاط صورة أو الاختيار من المعرض)، وتعهد «هذا التقرير حقيقي» الذي يجب تأكيده قبل التسجيل النهائي. ويخدم هذا التعهد الحفاظ على سلامة بيانات الشبكة.',
              ],
