                'ينزع الدماغ البشري إلى إيجاد الأنماط. وعندما يقضي الراصد ساعات يبحث بشغف عن الهلال قد يفسّر أنماطاً غامضة تفسيراً خاطئاً بأنها هلال. وتُسمّى هذه الظاهرة النفسية «باريدوليا» (Pareidolia)، وهي مع الأخطاء البصرية قد تقود حتى الراصدين ذوي الخبرة إلى تسجيل «تقرير رؤية كاذب». فليس كل قوس مضيء في السماء هلالَ القمر بالضرورة، وعلى الراصد، قبل تسجيل التقرير، أن يفحص هذه الحالات الشائعة فحصاً نقدياً:',
