                'اختبار التمييز (الحركة): اطرف بعينيك وحرّك رأسك قليلاً. فإذا تحرك القوس بحركة الرأس أو العين فهو رمش. أما الهلال الحقيقي فلا يتغير موضعه في مجال رؤية الأداة بتحريك رأس الراصد.',
                '٢. أثر الطائرة (Contrail) وحافة غيوم السيروس',
