                'اختبار التمييز (الزمن والهندسة): راقب القوس بضع دقائق. فحافة الغيمة وأثر الطائرة يغيّران شكلهما عادةً بسرعة أو يزدادان سمكاً أو يتلاشيان. أما الهلال الحقيقي فيحتفظ بشكله الهندسي الثابت ولا يتحرك إلا ببطء نحو الأفق بالحركة اليومية. كما يجب أن يتفق اتجاه بطن القوس مع هندسة الإضاءة (الدرس ٢.٣): فبطن الهلال المسائي يجب أن يتجه نحو موضع غروب الشمس.',
